function isTestDashboardAlert(alert: DashboardDTO["alerts"][number]) {
  const text = `${alert.title} ${alert.reason} ${alert.explanation || ""}`.toLowerCase();
  return text.includes("test alert") || text.includes("selected alert channel") || text.includes("confirms the selected alert");
}

function isDeprecatedLocalStoreAlert(alert: DashboardDTO["alerts"][number]) {
  const text = `${alert.title} ${alert.reason} ${alert.explanation || ""}`.toLowerCase();
  return (
    alert.entityType === "STORE" ||
    text.includes("field result") ||
    text.includes("store sighting") ||
    text.includes("shelf sighting") ||
    text.includes("local restock") ||
    text.includes("store restock") ||
    text.includes("vendor spotted")
  );
}

function alertTargetTab(alert: DashboardDTO["alerts"][number]): Tab {
  if (alert.entityType === "RELEASE") return "releases";
  if (alert.entityType === "PRODUCT" || alert.entityType === "STORE" || alert.entityType === "CARD") return "alerts";
  return "alerts";
}

type TrackerAlertView = "live" | "check" | "watchlist" | "keywords" | "history" | "scanner" | "system";

type TrackerAlertCategory =
  | "tracker_online_drop"
  | "tracker_local_stock"
  | "tracker_keyword_match"
  | "tracker_sku_match"
  | "tracker_price_change"
  | "tracker_preorder_live"
  | "tracker_add_to_cart"
  | "tracker_sold_out"
  | "inventory_low_stock"
  | "inventory_market_missing"
  | "order_paid"
  | "order_needs_fulfillment"
  | "system_warning"
  | "system_error"
  | "deprecated_local_store";

type TrackerAlertRecord = {
  alert: DashboardDTO["alerts"][number];
  product: ProductDTO | null;
  category: TrackerAlertCategory;
  channel: string;
  statusLabel: string;
  statusTone: string;
  isDeprecated: boolean;
  isSystem: boolean;
  isMuted: boolean;
  duplicateKey: string;
};

type RetailerCheckStockResult = {
  retailer: "Best Buy" | "GameStop" | "Pokemon Center";
  sku: string;
  zip: string;
  radiusMiles: number;
  sourceAvailable: boolean;
  message: string;
  checkedAt: string;
  stores: Array<{
    storeName: string;
    address: string;
    distanceMiles: number | null;
    availability: string;
  }>;
  onlineProduct: {
    id: string;
    name: string;
    imageUrl: string | null;
    productUrl: string;
    price: number | null;
    stockStatus: ProductStatus | string | null;
    lastCheckedAt: string | null;
    confidence: number | null;
    verificationStatus: ProductVerificationStatus | string;
  } | null;
};

const trackerViews: Array<{ id: TrackerAlertView; label: string; icon: typeof Radar }> = [
  { id: "live", label: "Live Drops", icon: Bell },
  { id: "check", label: "Check Stock", icon: Search },
  { id: "watchlist", label: "My Watchlist", icon: Eye },
  { id: "keywords", label: "Keywords", icon: Tags },
  { id: "history", label: "Alert History", icon: History },
  { id: "scanner", label: "Scanner Status", icon: Radar },
  { id: "system", label: "System Alerts", icon: AlertTriangle }
];

const trackerChannelFilters = ["All", "Target", "Walmart", "Best Buy", "Amazon", "GameStop", "Pokemon Center", "In Stock", "Add To Cart", "High Stock", "Low Stock", "Preorders", "Sold Out", "Price Drops"];
const watchlistRetailerFilters = ["All", "Target", "Best Buy", "GameStop", "Pokemon Center"] as const;
const trackerDefaultPositiveKeywords = ["Chaos Rising", "Perfect Order", "ETB", "Booster Bundle", "Premium Collection"];
const trackerDefaultNegativeKeywords = ["sleeves", "plush", "jumbo", "Japanese", "damaged"];

function trackerAlertText(alert: DashboardDTO["alerts"][number], product?: ProductDTO | null) {
  return `${alert.title} ${alert.reason} ${alert.explanation || ""} ${alert.entityType} ${alert.actionUrl || ""} ${product?.name || ""} ${
    product?.retailerName || ""
  } ${product?.sku || ""} ${product?.upc || ""} ${product?.dpci || ""} ${product?.retailerProductId || ""}`.toLowerCase();
}

function trackerKeywordMatch(text: string, positiveKeywords: string[], negativeKeywords: string[]) {
  const normalized = text.toLowerCase();
  const blockedBy = negativeKeywords.find((keyword) => keyword.trim() && normalized.includes(keyword.trim().toLowerCase())) || null;
  if (blockedBy) return { matched: false, blockedBy, matchedBy: null };
  const matchedBy = positiveKeywords.find((keyword) => keyword.trim() && normalized.includes(keyword.trim().toLowerCase())) || null;
  return { matched: Boolean(matchedBy), blockedBy: null, matchedBy };
}

function trackerSkuMatch(text: string, product: ProductDTO | null) {
  if (!product) return false;
  const normalized = text.toLowerCase();
  return [product.sku, product.upc, product.dpci, product.retailerProductId]
    .filter(Boolean)
    .some((identifier) => normalized.includes(String(identifier).toLowerCase()));
}

function trackerMuted(alert: DashboardDTO["alerts"][number]) {
  return Boolean(alert.suppressedAt);
}

function trackerDuplicateCooldownKey(alert: DashboardDTO["alerts"][number], product: ProductDTO | null) {
  return alert.dedupeKey || `${alert.entityType}:${alert.entityId || product?.id || alert.title}:${alert.actionUrl || ""}`;
}

function trackerProductImage(product: ProductDTO | null) {
  return product?.liveImageUrl || product?.imageUrl || null;
}

function trackerProductPrice(product: ProductDTO | null) {
  if (!product) return null;
  if (product.livePrice !== null && product.livePriceVerifiedAt) return product.livePrice;
  return product.retailPrice;
}

function trackerFindProduct(alert: DashboardDTO["alerts"][number], products: ProductDTO[]) {
  if (alert.entityType === "PRODUCT" && alert.entityId) {
    const byId = products.find((product) => product.id === alert.entityId);
    if (byId) return byId;
  }
  const text = trackerAlertText(alert);
  return (
    products.find((product) => {
      const identifiers = [product.url, product.verifiedFinalUrl, product.sku, product.upc, product.dpci, product.retailerProductId]
        .filter(Boolean)
        .map((value) => String(value).toLowerCase());
      return identifiers.some((identifier) => identifier.length > 4 && text.includes(identifier));
    }) ||
    products.find((product) => {
      const name = product.name.toLowerCase();
      return name.length > 8 && text.includes(name.slice(0, Math.min(name.length, 45)));
    }) ||
    null
  );
}

function trackerChannel(product: ProductDTO | null, alert: DashboardDTO["alerts"][number]) {
  const text = trackerAlertText(alert, product);
  const retailer = (product?.retailerName || "").toLowerCase();
  const source = retailer || text;
  if (source.includes("target")) {
    if (text.includes("high stock") || text.includes("large stock") || alert.score >= 75) return "Target Big Stock";
    return "Target Small Stock";
  }
  if (source.includes("walmart")) return "Walmart";
  if (source.includes("best buy")) {
    if (text.includes("high stock") || text.includes("available in many stores") || alert.score >= 80) return "High Stock";
    if (text.includes("low stock") || text.includes("limited stock") || text.includes("only a few left")) return "Low Stock";
    return "Best Buy";
  }
  if (source.includes("amazon")) return "Amazon";
  if (source.includes("gamestop")) {
    if (text.includes("price drop")) return "Price Drop";
    if (text.includes("preorder") || text.includes("pre-order")) return "Preorder Live";
    if (text.includes("add to cart")) return "Add To Cart Available";
    if (text.includes("sold out") || text.includes("out of stock")) return "Sold Out";
    return "GameStop";
  }
  if (source.includes("pokemon center") || source.includes("pokemoncenter")) return "Pokemon Center";
  if (source.includes("ebay")) return "eBay Deals";
  return "Other Pokemon";
}

function trackerStatus(product: ProductDTO | null, alert: DashboardDTO["alerts"][number]) {
  const text = trackerAlertText(alert, product);
  const status = product?.liveStockStatus || product?.stockStatus || null;
  if (text.includes("price")) return { label: "Price Drop", tone: "watch" };
  if (text.includes("preorder") || status === "PREORDER_LIVE") return { label: "Preorder Live", tone: "good" };
  if (text.includes("add to cart") || status === "ADD_TO_CART_AVAILABLE") return { label: "Add To Cart", tone: "good" };
  if (text.includes("sold out") || status === "SOLD_OUT") return { label: "Sold Out", tone: "muted" };
  if (text.includes("high stock") || alert.score >= 80) return { label: "High Stock", tone: "good" };
  if (text.includes("low stock") || text.includes("limited stock") || text.includes("only a few left")) return { label: "Low Stock", tone: "watch" };
  if (status === "IN_STOCK") return { label: "In Stock", tone: "good" };
  if (status === "PRICE_CHANGE") return { label: "Price Drop", tone: "watch" };
  if (status === "PAGE_UPDATED") return { label: "Page Updated", tone: "watch" };
  return { label: alert.priority === "HIGH" ? "In Stock" : "Watch", tone: statusTone(alert.priority) };
}

function trackerCategory(alert: DashboardDTO["alerts"][number], product: ProductDTO | null): TrackerAlertCategory {
  if (isDeprecatedLocalStoreAlert(alert)) return "deprecated_local_store";
  const text = trackerAlertText(alert, product);
  if (isTestDashboardAlert(alert)) return "system_warning";
  if (alert.dedupeKey?.startsWith("tracker_online_drop:") || text.includes("tracker_online_drop")) return "tracker_online_drop";
  if (text.includes("error") || text.includes("failed") || text.includes("webhook") || text.includes("parser")) return "system_error";
  if (text.includes("blocked") || text.includes("captcha") || text.includes("cron") || text.includes("provider") || text.includes("not configured") || text.includes("sync")) {
    return "system_warning";
  }
  if (alert.entityType === "ORDER") return text.includes("paid") || text.includes("completed") ? "order_paid" : "order_needs_fulfillment";
  if (alert.entityType === "INVENTORY") return text.includes("market") || text.includes("price") ? "inventory_market_missing" : "inventory_low_stock";
  if (alert.entityType === "RELEASE") return text.includes("preorder") ? "tracker_preorder_live" : "system_warning";
  if (alert.entityType === "PRODUCT" || product || alert.actionUrl) {
    if (text.includes("sold out")) return "tracker_sold_out";
    if (text.includes("price")) return "tracker_price_change";
    if (text.includes("preorder") || text.includes("add to cart") || text.includes("in stock") || text.includes("detected")) {
      return "tracker_online_drop";
    }
    if (trackerSkuMatch(text, product)) return "tracker_sku_match";
    return "tracker_online_drop";
  }
  return "system_warning";
}

function trackerClassifyAlert(alert: DashboardDTO["alerts"][number], products: ProductDTO[]): TrackerAlertRecord {
  const product = trackerFindProduct(alert, products);
  const category = trackerCategory(alert, product);
  const status = trackerStatus(product, alert);
  const isDeprecated = category === "deprecated_local_store";
  const isSystem = category === "system_warning" || category === "system_error" || isDeprecated;
  return {
    alert,
    product,
    category,
    channel: trackerChannel(product, alert),
    statusLabel: isDeprecated ? "Deprecated" : status.label,
    statusTone: isDeprecated ? "muted" : status.tone,
    isDeprecated,
    isSystem,
    isMuted: trackerMuted(alert),
    duplicateKey: trackerDuplicateCooldownKey(alert, product)
  };
}

function trackerIsLiveDrop(record: TrackerAlertRecord) {
  const text = trackerAlertText(record.alert, record.product);
  const explicitTrackerDrop = record.alert.dedupeKey?.startsWith("tracker_online_drop:") || text.includes("tracker_online_drop");
  const buyableProductStatus = ["IN_STOCK", "ADD_TO_CART_AVAILABLE", "PREORDER_LIVE"].includes(
    record.product?.liveStockStatus || record.product?.stockStatus || ""
  );
  const priceDropWithoutBuyableStock = record.statusLabel === "Price Drop" && !buyableProductStatus && !record.alert.dedupeKey?.includes(":simulated:");
  return (
    !priceDropWithoutBuyableStock &&
    !record.isSystem &&
    record.category === "tracker_online_drop" &&
    record.alert.entityType === "PRODUCT" &&
    Boolean(record.product) &&
    !record.isDeprecated &&
    !record.alert.suppressedAt &&
    !record.isMuted &&
    !isTestDashboardAlert(record.alert) &&
    (explicitTrackerDrop || text.includes("urgent") || text.includes("detected") || text.includes("manual checkout only") || text.includes("exact product link"))
  );
}

function trackerChannelMatches(record: TrackerAlertRecord, filter: string) {
  if (filter === "All") return true;
  if (filter === "In Stock") return record.statusLabel === "In Stock";
  if (filter === "Add To Cart") return record.statusLabel === "Add To Cart" || record.statusLabel === "Add To Cart Available";
  if (filter === "High Stock") return record.statusLabel === "High Stock";
  if (filter === "Low Stock") return record.statusLabel === "Low Stock" || record.channel === "Low Stock";
  if (filter === "Preorders") return record.statusLabel === "Preorder Live" || trackerAlertText(record.alert, record.product).includes("preorder");
  if (filter === "Sold Out") return record.statusLabel === "Sold Out" || record.channel === "Sold Out";
  if (filter === "Price Drops") return record.category === "tracker_price_change" || record.statusLabel === "Price Drop" || trackerAlertText(record.alert, record.product).includes("price drop");
  if (filter === "Best Buy") return trackerAlertText(record.alert, record.product).includes("best buy") || (record.product?.retailerName || "").toLowerCase().includes("best buy");
  if (filter === "GameStop") return trackerAlertText(record.alert, record.product).includes("gamestop") || (record.product?.retailerName || "").toLowerCase().includes("gamestop");
  if (filter === "Pokemon Center") return trackerAlertText(record.alert, record.product).includes("pokemon center") || (record.product?.retailerName || "").toLowerCase().includes("pokemon center");
  return record.channel.toLowerCase().includes(filter.toLowerCase());
}

function trackerWatchPrefillFromRecord(record: TrackerAlertRecord): WatchProductPrefill {
  const product = record.product;
  return {
    retailerId: product?.retailerId,
    name: product?.name || record.alert.title.replace(/^URGENT\s+/i, "").trim(),
    url: product?.verifiedFinalUrl || product?.url || record.alert.actionUrl || "",
    imageUrl: trackerProductImage(product),
    sku: product?.sku || null,
    upc: product?.upc || null,
    dpci: product?.dpci || null,
    retailerProductId: product?.retailerProductId || null,
    productType: product?.productType || record.channel,
    setName: product?.setName || product?.releaseName || null,
    requiredWords: product?.requiredWords || record.alert.title
  };
}

function AreaSetupPanel({
  dashboard,
  busy,
  busyLabel,
  submit,
  runAction
}: {
  dashboard: DashboardDTO;
  busy: boolean;
  busyLabel: string | null;
  submit: SubmitHandler;
  runAction: ActionHandler;
}) {
  const locationSaved = dashboard.userAreaPreferences.currentLatitude !== null && dashboard.userAreaPreferences.currentLongitude !== null;

  return (
    <section className="zone-panel">
      <div>
        <p className="eyeline">Deprecated area setup</p>
        <h2>{zoneDisplay(dashboard.userAreaPreferences.preferredZone, dashboard)}</h2>
        <p>
          Field Mode and dashboard store lists prioritize nearby and favorite stores first. Hide non-zone stores when you only
          want the route you actually check.
        </p>
        <p>Admin default zone = Miami. Switch zones only when you are intentionally planning a different route.</p>
      </div>
      <div className="location-save-row">
        <div>
          <strong>{locationSaved ? "Browser location saved" : "Browser location not saved"}</strong>
          <span>
            {locationSaved
              ? `Nearby sorting updated ${relativeTime(dashboard.userAreaPreferences.locationUpdatedAt)}.`
              : "Save location once on your phone so dashboard and Field Mode stores start closest to you."}
          </span>
        </div>
        <button
          className="mini-action solid"
          disabled={busy}
          type="button"
          onClick={() => saveBrowserLocation(dashboard, runAction)}
        >
          <MapPin size={14} />
          {busyLabel === "Saving browser location" ? "Saving" : "Location Disabled"}
        </button>
      </div>
      <form
        className="form-grid"
        onSubmit={(event) =>
          submit(
            event,
            "Saving area preferences",
            (form) =>
              requestJson("/api/radar/area-preferences", {
                method: "PATCH",
                body: JSON.stringify(formJson(form))
              }),
            { reset: false, success: "Area preferences saved" }
          )
        }
      >
        <SelectInput
          name="preferredZone"
          label="Default zone"
          defaultValue={dashboard.userAreaPreferences.preferredZone}
          options={dashboard.zoneOptions}
        />
        <TextInput name="customZoneName" label="Custom zone name" defaultValue={dashboard.userAreaPreferences.customZoneName ?? ""} />
        <label className="checkbox-label">
          <input name="hideDistantStores" type="hidden" value="false" />
          <input
            name="hideDistantStores"
            type="checkbox"
            value="true"
            defaultChecked={dashboard.userAreaPreferences.hideDistantStores}
          />
          Hide non-zone stores unless favorited
        </label>
        <button className="primary-action" disabled={busy} type="submit">
          <Save size={16} />
          {busyLabel === "Saving area preferences" ? "Saving" : "Save Area"}
        </button>
      </form>
    </section>
  );
}

function StoreCoveragePanel({ dashboard }: { dashboard: DashboardDTO }) {
  const storesWithDistance = dashboard.stores.filter((store) => store.distanceMiles !== null);
  const stats = [
    { label: "Saved stores", value: dashboard.stores.length, detail: "total coverage" },
    { label: "Within 5 miles", value: storesWithDistance.filter((store) => (store.distanceMiles ?? 999) <= 5).length, detail: "near route" },
    { label: "Within 10 miles", value: storesWithDistance.filter((store) => (store.distanceMiles ?? 999) <= 10).length, detail: "local loop" },
    { label: "Favorites", value: dashboard.stores.filter((store) => store.isFavorite).length, detail: "top priority" },
    { label: "Sightings logged", value: dashboard.sightings.length, detail: "manual reports" }
  ];

  return (
    <section className="form-panel store-coverage-panel">
      <div className="edit-card-heading">
        <div>
          <p className="eyeline">Deprecated store coverage</p>
          <h2>Nearby Store Network</h2>
          <span>Coverage uses saved browser location when available, with favorites sorted first.</span>
        </div>
      </div>
      <div className="coverage-grid">
        {stats.map((item) => (
          <div className="coverage-tile" key={item.label}>
            <strong>{item.value}</strong>
            <span>{item.label}</span>
            <small>{item.detail}</small>
          </div>
        ))}
      </div>
    </section>
  );
}

function StoreDiscoveryPanel({
  dashboard,
  isAdmin,
  busy,
  busyLabel,
  runAction
}: {
  dashboard: DashboardDTO;
  isAdmin: boolean;
  busy: boolean;
  busyLabel: string | null;
  runAction: ActionHandler;
}) {
  const [discoveryResult, setDiscoveryResult] = useState<StoreDiscoveryResponseDTO | null>(null);
  const [discoveryError, setDiscoveryError] = useState<string | null>(null);
  const [searching, setSearching] = useState(false);
  const [locating, setLocating] = useState(false);
  const [coords, setCoords] = useState<{ latitude: number; longitude: number } | null>(
    dashboard.userAreaPreferences.currentLatitude !== null && dashboard.userAreaPreferences.currentLongitude !== null
      ? {
          latitude: dashboard.userAreaPreferences.currentLatitude,
          longitude: dashboard.userAreaPreferences.currentLongitude
        }
      : null
  );
  const [selectedIds, setSelectedIds] = useState<Set<string>>(() => new Set());
  const addableCandidates = discoveryResult?.candidates.filter((candidate) => !candidate.duplicate) ?? [];
  const selectedCandidates = addableCandidates.filter((candidate) => selectedIds.has(candidate.id));

  async function useBrowserLocationForDiscovery() {
    setLocating(true);
    setDiscoveryError(null);
    try {
      const position = await browserPosition();
      setCoords({ latitude: position.coords.latitude, longitude: position.coords.longitude });
    } catch (error) {
      setDiscoveryError(error instanceof Error ? error.message : "Could not read browser location");
    } finally {
      setLocating(false);
    }
  }

  async function searchStores(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const form = event.currentTarget;
    const data = new FormData(form);
    const retailers = data.getAll("retailers").map(String);
    setSearching(true);
    setDiscoveryError(null);
    try {
      const result = await requestJson<StoreDiscoveryResponseDTO>("/api/radar/stores/discovery", {
        method: "POST",
        body: JSON.stringify({
          locationQuery: String(data.get("locationQuery") || "").trim(),
          latitude: coords?.latitude,
          longitude: coords?.longitude,
          radiusMiles: data.get("radiusMiles"),
          retailers
        })
      });
      setDiscoveryResult(result);
      setSelectedIds(new Set(result.candidates.filter((candidate) => !candidate.duplicate).map((candidate) => candidate.id)));
    } catch (error) {
      setDiscoveryError(error instanceof Error ? error.message : "Store discovery failed");
    } finally {
      setSearching(false);
    }
  }

  function toggleCandidate(candidateId: string) {
    setSelectedIds((current) => {
      const next = new Set(current);
      if (next.has(candidateId)) next.delete(candidateId);
      else next.add(candidateId);
      return next;
    });
  }

  return (
    <section className="form-panel store-discovery-panel">
      <div className="edit-card-heading">
        <div>
          <p className="eyeline">Deprecated store discovery</p>
          <h2>Store discovery hidden</h2>
          <span>Use public Google Places when configured, or stay in manual CSV/JSON import mode.</span>
        </div>
        <span className="chip muted">{coords ? "Location ready" : "ZIP/city or browser location"}</span>
      </div>
      <div className="template-hint warning">
        <strong>Store discovery setup</strong>
        <span>Nearby store discovery requires GOOGLE_PLACES_API_KEY. Without it, import or add stores manually.</span>
      </div>
      <form className="store-discovery-form" onSubmit={searchStores}>
        <TextInput
          name="locationQuery"
          label="ZIP code or city"
          placeholder="33126 or Miami, FL"
          defaultValue={dashboard.userAreaPreferences.currentLatitude !== null ? "" : zoneDisplay(dashboard.userAreaPreferences.preferredZone, dashboard)}
        />
        <SelectInput
          name="radiusMiles"
          label="Radius"
          defaultValue="10"
          options={[5, 10, 25, 50].map((value) => ({ value: String(value), label: `${value} miles` }))}
        />
        <div className="retailer-chip-grid" aria-label="Retailers">
          {["Target", "Walmart", "GameStop", "Best Buy"].map((retailer) => (
            <label className="checkbox-label" key={retailer}>
              <input name="retailers" type="checkbox" value={retailer} defaultChecked />
              {retailer}
            </label>
          ))}
        </div>
        <div className="form-actions">
          <button className="mini-action" disabled={searching || locating || busy} type="button" onClick={useBrowserLocationForDiscovery}>
            <MapPin size={14} />
            {locating ? "Locating" : "Browser Location Disabled"}
          </button>
          <button className="primary-action" disabled={searching || busy} type="submit">
            <Store size={16} />
            {searching ? "Searching" : "Find Stores"}
          </button>
        </div>
      </form>
      {discoveryError ? <p className="form-error">{discoveryError}</p> : null}
      {discoveryResult ? (
        <div className="discovery-results">
          <div className="edit-card-heading">
            <div>
              <strong>{discoveryResult.message}</strong>
              <span>
                Origin: {discoveryResult.origin.label} - Radius {discoveryResult.radiusMiles} miles
              </span>
            </div>
            <span className={`chip ${discoveryResult.configured ? "good" : "watch"}`}>
              {discoveryResult.configured ? "Google Places" : "Manual mode"}
            </span>
          </div>
          {!discoveryResult.configured ? (
            <div className="template-hint warning">
              <strong>Manual mode</strong>
              <span>Nearby store discovery requires GOOGLE_PLACES_API_KEY. Without it, import or add stores manually.</span>
            </div>
          ) : null}
          {discoveryResult.candidates.length ? (
            <div className="candidate-store-list">
              {discoveryResult.candidates.map((candidate) => (
                <label className={candidate.duplicate ? "candidate-store-row duplicate" : "candidate-store-row"} key={candidate.id}>
                  <input
                    type="checkbox"
                    checked={selectedIds.has(candidate.id)}
                    disabled={candidate.duplicate}
                    onChange={() => toggleCandidate(candidate.id)}
                  />
                  <div>
                    <strong>{candidate.storeName}</strong>
                    <span>
                      {candidate.retailerName} - {candidate.address}, {candidate.city}, {candidate.state}
                      {candidate.distanceMiles !== null ? ` - ${candidate.distanceMiles} mi` : ""}
                    </span>
                    <small>
                      {candidate.phone || "Phone unavailable"}
                      {candidate.placeId ? ` - place_id ${candidate.placeId}` : ""}
                    </small>
                  </div>
                  <span className={`chip ${candidate.duplicate ? "muted" : "good"}`}>
                    {candidate.duplicate ? "Already saved" : "Addable"}
                  </span>
                  {candidate.duplicateReason ? <small>{candidate.duplicateReason}</small> : null}
                </label>
              ))}
            </div>
          ) : (
            <EmptyState
              icon={Store}
              title={discoveryResult.configured ? "No candidates found" : "Manual store setup ready"}
              detail="Try a wider radius, different city/ZIP, manual entry, or bulk import."
            />
          )}
          {isAdmin ? (
            <button
              className="primary-action"
              aria-label="Add Store Disabled"
              disabled={busy || selectedCandidates.length === 0}
              type="button"
              onClick={() =>
                runAction(
                  "Adding discovered stores",
                  async () => {
                    const result = await requestJson<{ created: number; skipped: number; errors: string[] }>(
                      "/api/radar/stores/discovery/add",
                      {
                        method: "POST",
                        body: JSON.stringify({ candidates: selectedCandidates })
                      }
                    );
                    if (result.created === 0 && result.skipped > 0) {
                      throw new Error(result.errors.slice(0, 2).join(" ") || "All selected stores were duplicates.");
                    }
                  },
                  { success: `${selectedCandidates.length} selected store${selectedCandidates.length === 1 ? "" : "s"} processed` }
                )
              }
            >
              <Plus size={16} />
              {busyLabel === "Adding discovered stores" ? "Adding" : `Add ${selectedCandidates.length} To My Stores`}
            </button>
          ) : (
            <p className="push-copy">Ask an Admin to add discovered stores to the shared private store list.</p>
          )}
        </div>
      ) : null}
    </section>
  );
}

function TodayPlanPanel({
  dashboard,
  setActiveTab,
  busy,
  busyLabel,
  runAction
}: {
  dashboard: DashboardDTO;
  setActiveTab: (tab: Tab) => void;
  busy: boolean;
  busyLabel: string | null;
  runAction: ActionHandler;
}) {
  function inventorySubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const form = event.currentTarget;
    runAction(
      "Logging inventory",
      async () => {
        await requestJson("/api/radar/inventory", { method: "POST", body: JSON.stringify(formJson(form)) });
        form.reset();
      },
      { success: "Inventory item logged" }
    );
  }

  function presetSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const form = event.currentTarget;
    runAction(
      "Saving filter preset",
      async () => {
        await requestJson("/api/radar/filter-presets", { method: "POST", body: JSON.stringify(formJson(form)) });
        form.reset();
      },
      { success: "Filter preset saved" }
    );
  }

  return (
    <section className="today-plan-panel">
      <div className="panel-header">
        <div>
          <p className="eyeline">Morning workflow</p>
          <h2>Today&apos;s Plan</h2>
        </div>
        <button
          className="mini-action solid"
          disabled={busy}
          type="button"
          onClick={() =>
            runAction(
              "Generating daily recap",
              () => requestJson("/api/radar/daily-recaps", { method: "POST", body: JSON.stringify({}) }),
              { success: "Daily recap archived" }
            )
          }
        >
          <FileText size={14} />
          {busyLabel === "Generating daily recap" ? "Generating" : "Generate Recap"}
        </button>
      </div>
      <div className="quick-action-grid">
        <button className="mini-action solid" type="button" onClick={() => setActiveTab("inventory")}>
          <Plus size={14} />
          Open Inventory
        </button>
        <button className="mini-action solid" type="button" onClick={() => setActiveTab("orders")}>
          <ShoppingBag size={14} />
          Review Orders
        </button>
        <button className="mini-action" type="button" onClick={() => setActiveTab("alerts")}><Bell size={14} />Alerts</button>
        <button className="mini-action" type="button" onClick={() => setActiveTab("releases")}><CalendarDays size={14} />Releases</button>
      </div>
      <div className="daily-plan-grid">
        <PlanList title="Latest alerts" tab="alerts" setActiveTab={setActiveTab}>
          <div className="stack compact">
            {dashboard.dailyPlan.latestAlerts.length ? (
              dashboard.dailyPlan.latestAlerts.slice(0, 4).map((alert) => (
                <article className="data-card compact-card" key={alert.id}>
                  <div className="card-main">
                    <div className="avatar">
                      <Bell size={15} />
                    </div>
                    <div>
                      <h3>{alert.title}</h3>
                      <p>{alert.reason}</p>
                    </div>
                  </div>
                  <span className={`chip ${statusTone(alert.priority)}`}>{alert.priority}</span>
                </article>
              ))
            ) : (
              <EmptyState icon={Bell} title="No alerts yet" detail="Inventory, order, release, and storefront alerts will appear here." />
            )}
          </div>
        </PlanList>
        <PlanList title="Newest releases" tab="releases" setActiveTab={setActiveTab}>
          <ReleaseStack releases={dashboard.dailyPlan.newestReleases.slice(0, 3)} />
        </PlanList>
        <PlanList title="Recent inventory" tab="inventory" setActiveTab={setActiveTab}>
          <div className="stack compact">
            {dashboard.inventory.slice(0, 3).map((item) => (
              <article className="data-card compact-card" key={item.id}>
                <div className="card-main">
                  <ProductImagePreview imageUrl={item.imageUrl || ""} itemName={item.itemName} />
                  <div>
                    <h3>{item.itemName}</h3>
                    <p>{item.quantityOwned} owned - {money(item.totalCost)} cost basis</p>
                  </div>
                </div>
              </article>
            ))}
            {!dashboard.inventory.length ? <EmptyState icon={Trophy} title="No inventory yet" detail="Add products you own from Inventory." /> : null}
          </div>
        </PlanList>
      </div>
      <div className="split-grid">
        <section className="push-panel">
          <h3>Inventory Log</h3>
          <form className="form-grid" onSubmit={inventorySubmit}>
            <SelectInput
              name="itemType"
              label="Type"
              defaultValue="product"
              options={["product", "card", "sealed", "other"].map((value) => ({ value, label: formatStatus(value) }))}
            />
            <TextInput name="itemName" label="Product/card purchased" required />
            <TextInput name="cost" label="Cost" type="number" min="0" step="0.01" required />
            <TextInput name="quantity" label="Quantity" type="number" min="1" defaultValue="1" required />
            <TextInput name="source" label="Source" placeholder="Target, Pokemon Center, eBay" required />
            <TextInput name="purchasedAt" label="Purchase date" type="date" required />
            <TextareaInput name="expectedPlan" label="Expected resale/grading plan" wide />
            <button className="primary-action" disabled={busy} type="submit">
              <Save size={16} />
              {busyLabel === "Logging inventory" ? "Saving" : "Log Purchase"}
            </button>
          </form>
          {dashboard.inventory.length ? (
            <div className="inventory-list">
              {dashboard.inventory.slice(0, 5).map((item) => (
                <div className="access-row" key={item.id}>
                  <div>
                    <strong>{item.itemName}</strong>
                    <span>
                      {item.quantity} @ {money(item.cost)} from {item.source} - {shortDate(item.purchasedAt)}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <EmptyState icon={PackageSearch} title="No inventory logged" detail="Log purchases as you buy sealed products or raw cards." />
          )}
        </section>
        <section className="push-panel">
          <h3>Saved Filter Presets</h3>
          <form className="form-grid" onSubmit={presetSubmit}>
            <TextInput name="name" label="Preset name" placeholder="High-priority Target ETBs" required />
            <SelectInput name="section" label="Section" defaultValue="products" options={tabs.map((tab) => ({ value: tab.id, label: tab.label }))} />
            <TextareaInput name="filters" label="Filter JSON / notes" defaultValue='{"priority":"HIGH"}' wide required />
            <button className="mini-action solid" disabled={busy} type="submit">
              <Save size={14} />
              {busyLabel === "Saving filter preset" ? "Saving" : "Save Preset"}
            </button>
          </form>
          {dashboard.savedFilterPresets.length ? (
            dashboard.savedFilterPresets.slice(0, 6).map((preset) => (
              <div className="access-row" key={preset.id}>
                <div>
                  <strong>{preset.name}</strong>
                  <span>
                    {formatStatus(preset.section)} - {preset.filters}
                  </span>
                </div>
                <button
                  className="mini-action"
                  disabled={busy}
                  type="button"
                  onClick={() =>
                    runAction(
                      "Deleting filter preset",
                      () => requestJson(`/api/radar/filter-presets/${preset.id}`, { method: "DELETE" }),
                      { confirm: `Delete preset ${preset.name}?`, success: "Preset deleted" }
                    )
                  }
                >
                  <Trash2 size={14} />
                  Delete
                </button>
              </div>
            ))
          ) : (
            <EmptyState icon={FileText} title="No saved presets" detail="Save filter notes you use every morning." />
          )}
          <h3>Daily Recap Archive</h3>
          {dashboard.dailyRecaps.length ? (
            dashboard.dailyRecaps.slice(0, 5).map((recap) => (
              <div className="access-row" key={recap.id}>
                <div>
                  <strong>{shortDate(recap.recapDate)}</strong>
                  <span>{recap.summary}</span>
                </div>
              </div>
            ))
          ) : (
            <EmptyState icon={History} title="No recaps yet" detail="Generate a recap after morning checks or store runs." />
          )}
        </section>
      </div>
    </section>
  );
}

