function releasesNextMonth(releases: ReleaseDTO[]) {
  const now = new Date();
  const start = new Date(now.getFullYear(), now.getMonth() + 1, 1);
  const end = new Date(now.getFullYear(), now.getMonth() + 2, 0, 23, 59, 59, 999);
  return releases
    .filter((release) => {
      const date = calendarDate(release.officialReleaseDate);
      return Boolean(date && date >= start && date <= end && !release.needsReview);
    })
    .sort((a, b) => {
      const dateA = calendarDate(a.officialReleaseDate)?.getTime() ?? 0;
      const dateB = calendarDate(b.officialReleaseDate)?.getTime() ?? 0;
      return dateA - dateB;
    });
}

function releasesThisMonth(releases: ReleaseDTO[]) {
  const now = new Date();
  return releases.filter((release) => {
    const date = calendarDate(release.officialReleaseDate);
    return Boolean(date && date.getFullYear() === now.getFullYear() && date.getMonth() === now.getMonth() && !release.needsReview);
  });
}

function releaseDateLabel(release: ReleaseDTO) {
  return release.officialReleaseDate ? shortDate(release.officialReleaseDate) : "TBD";
}

function releaseTimingLabel(release: ReleaseDTO) {
  if (!release.officialReleaseDate) return "Date needs official confirmation";
  if (release.daysUntilRelease === null) return "Release timing unknown";
  if (release.daysUntilRelease < 0) return "Released";
  if (release.daysUntilRelease === 0) return "Releases today";
  if (release.daysUntilRelease === 1) return "Releases tomorrow";
  return `${release.daysUntilRelease} days away`;
}

function releaseSourceLabel(release: ReleaseDTO) {
  if (release.createdByManualEntry) return "Manual entry";
  return release.sourceName || (release.sourceType === "official" ? "Official source" : "Public source");
}

function releasePrimaryUrl(release: ReleaseDTO) {
  return release.productUrl || release.sourceUrl || firstUrl(release.productLinks);
}

function releaseSourceUrl(release: ReleaseDTO) {
  return release.sourceUrl;
}

function releasePatchPayload(release: ReleaseDTO, overrides: Partial<ReleaseDTO> = {}) {
  const next = { ...release, ...overrides };
  return {
    setName: next.setName,
    releaseName: next.releaseName ?? "",
    productName: next.productName ?? "",
    productType: next.productType ?? productTypeOptions[0],
    releaseType: next.releaseType || "product_drop",
    officialReleaseDate: next.officialReleaseDate ?? "",
    preorderDate: next.preorderDate ?? "",
    preorderWindowText: next.preorderWindowText ?? "",
    region: next.region || "US",
    retailer: next.retailer ?? "",
    productTypes: next.productTypes || next.productType || productTypeOptions[0],
    pokemonCenterExclusiveVersion: Boolean(next.pokemonCenterExclusiveVersion),
    productImage: next.productImage ?? "",
    productUrl: next.productUrl ?? "",
    chaseCards: next.chaseCards ?? "",
    demandRating: next.demandRating,
    estimatedDemand: next.estimatedDemand,
    priority: next.priority,
    sealedProductPriority: next.sealedProductPriority,
    notes: next.notes ?? "",
    productLinks: next.productLinks ?? "",
    sourceUrl: next.sourceUrl ?? "",
    sourceName: next.sourceName ?? "",
    sourceType: next.sourceType || "manual",
    confidence: next.confidence,
    status: next.status || "scheduled",
    createdByManualEntry: Boolean(next.createdByManualEntry),
    needsReview: Boolean(next.needsReview),
    reviewReason: next.reviewReason ?? ""
  };
}

function releaseStatusLabel(release: ReleaseDTO) {
  if (release.needsReview) return "Needs Review";
  if (!release.officialReleaseDate) return "TBD";
  if (release.status === "scheduled") return "Scheduled";
  if (release.status === "confirmed" || release.confidence === "HIGH") return "Confirmed";
  if (release.daysUntilRelease !== null && release.daysUntilRelease < 0) return "Released";
  return "Scheduled";
}

function releaseStatusTone(release: ReleaseDTO) {
  const label = releaseStatusLabel(release);
  if (label === "Needs Review") return "warn";
  if (label === "Scheduled") return "info";
  if (label === "Confirmed") return "good";
  return "";
}

function releaseSourceBadgeLabel(release: ReleaseDTO) {
  if (release.createdByManualEntry || release.sourceType === "manual") return "Manual";
  if (release.sourceType?.startsWith("official") || release.sourceType === "pokemon_tcg_api") return "Official";
  if (release.sourceType === "icv2_calendar") return "ICv2";
  return "Public";
}

function ReleasesPanel({
  dashboard,
  isAdmin,
  busy,
  busyLabel,
  runAction
}: {
  dashboard: DashboardDTO;
  isAdmin: boolean;
  busy: boolean;
  busyLabel: string | null;
  runAction: ActionHandler;
}) {
  const [view, setView] = useState<"month" | "year" | "upcoming">("month");
  const [filter, setFilter] = useState<"ALL" | "HIGH" | "PC" | "REVIEW">("ALL");
  const [selectedRelease, setSelectedRelease] = useState<ReleaseDTO | null>(null);
  const nextMonth = useMemo(() => releasesNextMonth(dashboard.releases), [dashboard.releases]);
  const thisMonth = useMemo(() => releasesThisMonth(dashboard.releases), [dashboard.releases]);
  const latestSyncLogs = dashboard.releaseSyncLogs.slice(0, 12);
  const latestSummaryLog = latestSyncLogs.find((log) => log.adapter === "merge") ?? latestSyncLogs[0] ?? null;
  const latestRunTime = latestSummaryLog?.checkedAt ?? null;
  const latestRunLogs = latestRunTime
    ? dashboard.releaseSyncLogs.filter((log) => Math.abs(new Date(log.checkedAt).getTime() - new Date(latestRunTime).getTime()) < 2000)
    : [];
  const usableSourceParsed = latestRunLogs
    .filter((log) => log.adapter !== "merge" && log.status !== "failed" && log.status !== "blocked")
    .reduce((total, log) => total + log.parsedCount, 0);
  const syncStats = {
    sourcesChecked: new Set(latestRunLogs.filter((log) => log.adapter !== "merge").map((log) => log.sourceUrl || log.sourceName)).size,
    succeeded: latestRunLogs.filter((log) => log.adapter !== "merge" && log.status === "active").length,
    blocked: latestRunLogs.filter((log) => log.adapter !== "merge" && log.status === "blocked").length,
    failed: latestRunLogs.filter((log) => log.adapter !== "merge" && log.status === "failed").length,
    needsReviewSources: latestRunLogs.filter((log) => log.adapter !== "merge" && log.status === "needs_review").length,
    parsed: latestRunLogs.reduce((total, log) => total + log.parsedCount, 0),
    ignoredArticleTitles: latestRunLogs.reduce((total, log) => total + log.warningCount, 0),
    created: latestRunLogs.reduce((total, log) => total + log.createdCount, 0),
    updated: latestRunLogs.reduce((total, log) => total + log.updatedCount, 0),
    conflicts: latestRunLogs.reduce((total, log) => total + log.conflictCount, 0),
    failures: latestRunLogs.filter((log) => log.adapter !== "merge" && (log.status === "failed" || log.status === "blocked")).length
  };
  const syncHealth = !latestRunTime
    ? { tone: "warn", label: "Not synced" }
    : usableSourceParsed === 0
      ? { tone: "danger", label: "Failed" }
      : syncStats.failures || syncStats.needsReviewSources
        ? { tone: "warn", label: "Warning" }
        : { tone: "good", label: "Clean" };
  const blockedFallbackMessage =
    latestRunTime && syncStats.blocked && usableSourceParsed
      ? "Official source blocked. Using Pokemon TCG API and ICv2 fallback until official source is accessible."
      : null;
  const upcoming = useMemo(
    () =>
      dashboard.releases
        .filter((release) => !release.needsReview && (release.daysUntilRelease === null || release.daysUntilRelease >= 0))
        .sort((a, b) => (calendarDate(a.officialReleaseDate)?.getTime() ?? Number.MAX_SAFE_INTEGER) - (calendarDate(b.officialReleaseDate)?.getTime() ?? Number.MAX_SAFE_INTEGER)),
    [dashboard.releases]
  );
  const filteredReleases = useMemo(() => {
    return dashboard.releases.filter((release) => {
      if (filter === "HIGH") return release.priority === "HIGH" || release.demandRating === "HIGH";
      if (filter === "PC") return release.pokemonCenterExclusiveVersion;
      if (filter === "REVIEW") return release.needsReview || !release.officialReleaseDate;
      return true;
    });
  }, [dashboard.releases, filter]);
  const nextDrop = upcoming.find((release) => release.officialReleaseDate && (release.status === "confirmed" || release.status === "scheduled" || release.createdByManualEntry)) ?? null;
  const nextPreorder = dashboard.releases
    .filter((release) => release.daysUntilPreorder !== null && release.daysUntilPreorder >= 0)
    .sort((a, b) => (a.daysUntilPreorder ?? 9999) - (b.daysUntilPreorder ?? 9999))[0] ?? null;
  const lastSync = dashboard.releases
    .map((release) => release.lastSyncedAt)
    .filter(Boolean)
    .sort()
    .at(-1) ?? null;
  const needsReview = dashboard.releases.filter((release) => release.needsReview);
  const tbdReleases = dashboard.releases.filter((release) => !release.needsReview && !release.officialReleaseDate);

  return (
    <section className="release-radar-page app-light-surface">
      <div className="release-radar-header">
        <div>
          <p className="eyeline">Release Radar</p>
          <h1>Pokemon TCG Release Calendar</h1>
          <span>Official dates show as Confirmed. Trusted product calendars show as Scheduled; only unclear parser results need review.</span>
        </div>
        <div className="release-radar-actions">
          {isAdmin ? (
            <button
              className="light-action primary"
              disabled={busy}
              type="button"
              onClick={() =>
                runAction(
                  "Syncing release news",
                  () => requestJson("/api/radar/releases/sync", { method: "POST" }),
                  { success: "Release calendar checked against public sources" }
                )
              }
            >
              <RefreshCw size={14} />
              {busyLabel === "Syncing release news" ? "Syncing" : "Sync Public Sources"}
            </button>
          ) : null}
          <button className="light-action" type="button" onClick={() => document.getElementById("manual-release-form")?.scrollIntoView({ behavior: "smooth" })}>
            <Plus size={14} />
            Manual Add
          </button>
        </div>
      </div>

      <div className="release-kpi-grid">
        <ReleaseMetricCard label="Next Drop" value={nextDrop ? nextDrop.setName : "TBD"} detail={nextDrop ? `${releaseDateLabel(nextDrop)} - ${releaseTimingLabel(nextDrop)}` : "No verified upcoming release"} icon={<CalendarDays size={18} />} />
        <ReleaseMetricCard label="Next Preorder" value={nextPreorder ? nextPreorder.setName : "TBD"} detail={nextPreorder ? `${shortDate(nextPreorder.preorderDate)} - ${nextPreorder.preorderWindowText || "Watch retailer windows"}` : "No verified preorder window"} icon={<Clock size={18} />} />
        <ReleaseMetricCard label="This Month" value={String(thisMonth.length)} detail="Verified releases this month" icon={<CalendarDays size={18} />} />
        <ReleaseMetricCard label="Next Month" value={String(nextMonth.length)} detail="Known drops in the next calendar month" icon={<TrendingUp size={18} />} />
        <ReleaseMetricCard label="Tracked" value={String(dashboard.releases.length)} detail={`${needsReview.length} need review, ${tbdReleases.length} TBD`} icon={<ClipboardList size={18} />} />
        <ReleaseMetricCard label="Last Sync" value={latestRunTime ? relativeTime(latestRunTime) : lastSync ? relativeTime(lastSync) : "Never"} detail="Public source refresh" icon={<RefreshCw size={18} />} />
      </div>

      <div className="release-source-strip">
        <div>
          <strong>Source sync</strong>
          <span>
            {latestRunTime
              ? `${syncStats.sourcesChecked} sources checked, ${syncStats.parsed} product releases parsed, ${syncStats.ignoredArticleTitles} article/source warnings, ${syncStats.created} new, ${syncStats.updated} updated, ${syncStats.blocked} blocked, ${syncStats.failed} failed.`
              : "Official Pokemon TCG, Pokemon News, Pokemon Center, ICv2, and configured feeds will be checked when you sync."}
            {blockedFallbackMessage ? ` ${blockedFallbackMessage}` : ""}
          </span>
        </div>
        <span className={`light-pill ${syncHealth.tone}`}>
          {syncHealth.label}
        </span>
      </div>

      {latestRunLogs.length ? (
        <section className="release-sync-log-panel">
          <div className="release-sync-log-heading">
            <div>
              <p className="eyeline">Release News / Source Articles</p>
              <h2>Latest source checks</h2>
            </div>
            <span>Last checked {relativeTime(latestRunTime || latestRunLogs[0].checkedAt)}</span>
          </div>
          <div className="release-sync-summary-grid" aria-label="Release sync summary">
            <span><strong>{syncStats.sourcesChecked}</strong> checked</span>
            <span><strong>{syncStats.succeeded}</strong> succeeded</span>
            <span><strong>{syncStats.blocked}</strong> blocked</span>
            <span><strong>{syncStats.failed}</strong> failed</span>
            <span><strong>{syncStats.parsed}</strong> parsed</span>
            <span><strong>{syncStats.ignoredArticleTitles}</strong> warnings</span>
            <span><strong>{syncStats.created}</strong> new</span>
            <span><strong>{syncStats.updated}</strong> updated</span>
            <span><strong>{syncStats.conflicts}</strong> conflicts</span>
          </div>
          <details className="release-sync-details">
            <summary>View source details</summary>
            <div className="release-sync-table" role="table" aria-label="Release source sync details">
              <div className="release-sync-table-head" role="row">
                <span>Source</span>
                <span>Status</span>
                <span>HTTP</span>
                <span>Parsed</span>
                <span>Added</span>
                <span>Updated</span>
                <span>Last checked</span>
                <span>Error</span>
              </div>
              {latestRunLogs.filter((log) => log.adapter !== "merge").map((log) => (
                <div className="release-sync-table-row" role="row" key={log.id}>
                  <span><strong>{log.sourceName}</strong><small>{log.sourceUrl || log.adapter}</small></span>
                  <span><span className={`light-pill ${log.status === "active" ? "good" : log.status === "failed" || log.status === "blocked" ? "danger" : "warn"}`}>{log.status}</span></span>
                  <span>{log.httpStatus ?? "n/a"}</span>
                  <span>{log.parsedCount}</span>
                  <span>{log.createdCount}</span>
                  <span>{log.updatedCount}</span>
                  <span>{relativeTime(log.checkedAt)}</span>
                  <span>{log.error || "None"}</span>
                </div>
              ))}
            </div>
          </details>
        </section>
      ) : null}

      <div className="release-view-toolbar">
        <div className="release-view-tabs">
          {(["month", "year", "upcoming"] as const).map((option) => (
            <button className={view === option ? "active" : ""} key={option} type="button" onClick={() => setView(option)}>
              {option === "month" ? "Monthly" : option === "year" ? "Year" : "Upcoming"}
            </button>
          ))}
        </div>
        <select value={filter} onChange={(event) => setFilter(event.currentTarget.value as typeof filter)}>
          <option value="ALL">All releases</option>
          <option value="HIGH">High demand</option>
          <option value="PC">Pokemon Center exclusive</option>
          <option value="REVIEW">Needs review / TBD</option>
        </select>
      </div>

      {view === "year" ? <ReleaseCalendar releases={filteredReleases} onSelect={setSelectedRelease} /> : null}
      {view === "month" ? <ReleaseMonthView releases={filteredReleases} onSelect={setSelectedRelease} /> : null}
      {view === "upcoming" ? <ReleaseUpcomingList releases={filteredReleases} onSelect={setSelectedRelease} /> : null}

      {needsReview.length ? (
        <section className="release-review-panel">
          <div>
            <p className="eyeline">Review Queue</p>
            <h2>Needs confirmation</h2>
            <span>These entries are missing an official date, have lower confidence, or came from a non-official feed.</span>
          </div>
          <div className="release-review-list">
            {needsReview.slice(0, 6).map((release) => (
              <button key={release.id} type="button" onClick={() => setSelectedRelease(release)}>
                <strong>{release.setName}</strong>
                <span>{release.reviewReason || "Date/source needs review"} - {releaseSourceLabel(release)}</span>
              </button>
            ))}
          </div>
        </section>
      ) : null}

      {selectedRelease ? (
        <ReleaseDetailModal
          busy={busy}
          busyLabel={busyLabel}
          isAdmin={isAdmin}
          release={selectedRelease}
          runAction={runAction}
          onClose={() => setSelectedRelease(null)}
        />
      ) : null}
    </section>
  );
}

function ReleaseMetricCard({ label, value, detail, icon }: { label: string; value: string; detail: string; icon: ReactNode }) {
  return (
    <article className="release-metric-card">
      <div className="release-metric-icon">{icon}</div>
      <small>{label}</small>
      <strong>{value}</strong>
      <span>{detail}</span>
    </article>
  );
}

function ReleaseCalendar({ releases, onSelect }: { releases: ReleaseDTO[]; onSelect: (release: ReleaseDTO) => void }) {
  const [showEmptyMonths, setShowEmptyMonths] = useState(false);
  const yearlyDrops = useMemo(() => groupReleasesByYear(releases, showEmptyMonths), [releases, showEmptyMonths]);

  if (!releases.length) {
    return (
      <section className="release-calendar-panel">
        <EmptyState
          icon={CalendarDays}
          title="No release dates tracked"
          detail="Sync public sources or add a manual release when a verified date is available."
        />
      </section>
    );
  }

  return (
    <section className="release-calendar-panel" aria-label="Pokemon TCG yearly release calendar">
      {yearlyDrops.map(({ year, months }) => (
        <div className="release-year" key={year}>
          <div className="release-year-heading">
            <div>
              <p className="eyeline">Pokemon TCG Drops</p>
              <h2>{year}</h2>
            </div>
            <div className="release-year-actions">
              <span className="chip muted">{months.reduce((total, month) => total + month.releases.length, 0)} tracked drops</span>
              <label className="release-empty-toggle">
                <input type="checkbox" checked={showEmptyMonths} onChange={(event) => setShowEmptyMonths(event.currentTarget.checked)} />
                Show empty months
              </label>
            </div>
          </div>
          <div className="release-year-timeline">
            {months.map((month) => (
              <article className={`release-month-section ${month.releases.length ? "" : "is-empty"}`} key={`${year}-${month.month}`}>
                <div className="release-month-heading">
                  <h3>{month.label} {year}</h3>
                  <span>{month.releases.length ? `${month.releases.length} release${month.releases.length === 1 ? "" : "s"}` : "No releases"}</span>
                </div>
                <div className="release-day-list">
                  {month.releases.map((release) => <ReleaseListRow key={release.id} release={release} onSelect={onSelect} />)}
                </div>
              </article>
            ))}
          </div>
        </div>
      ))}
    </section>
  );
}

function ReleaseMonthView({ releases, onSelect }: { releases: ReleaseDTO[]; onSelect: (release: ReleaseDTO) => void }) {
  const now = new Date();
  const monthReleases = releases.filter((release) => {
    const date = calendarDate(release.officialReleaseDate);
    return Boolean(date && date.getFullYear() === now.getFullYear() && date.getMonth() === now.getMonth());
  });
  const tbd = releases.filter((release) => !release.officialReleaseDate);
  return (
    <section className="release-calendar-panel">
      <div className="release-year-heading">
        <div>
          <p className="eyeline">Monthly Calendar</p>
          <h2>{new Intl.DateTimeFormat("en-US", { month: "long", year: "numeric" }).format(now)}</h2>
        </div>
        <span className="light-pill">{monthReleases.length} this month</span>
      </div>
      <div className="release-upcoming-list">
        {[...monthReleases, ...tbd].map((release) => (
          <ReleaseListRow key={release.id} release={release} onSelect={onSelect} />
        ))}
        {!monthReleases.length && !tbd.length ? <EmptyState icon={CalendarDays} title="No drops this month" detail="Upcoming verified releases will show here after sync." /> : null}
      </div>
    </section>
  );
}

function ReleaseUpcomingList({ releases, onSelect }: { releases: ReleaseDTO[]; onSelect: (release: ReleaseDTO) => void }) {
  const upcoming = releases
    .filter((release) => release.daysUntilRelease === null || release.daysUntilRelease >= 0)
    .sort((a, b) => (calendarDate(a.officialReleaseDate)?.getTime() ?? Number.MAX_SAFE_INTEGER) - (calendarDate(b.officialReleaseDate)?.getTime() ?? Number.MAX_SAFE_INTEGER));
  const now = new Date();
  const thisMonthStart = new Date(now.getFullYear(), now.getMonth(), 1);
  const nextMonthStart = new Date(now.getFullYear(), now.getMonth() + 1, 1);
  const laterThisYearStart = new Date(now.getFullYear(), now.getMonth() + 2, 1);
  const nextYearStart = new Date(now.getFullYear() + 1, 0, 1);
  const groups = [
    {
      label: "This Month",
      releases: upcoming.filter((release) => {
        const date = calendarDate(release.officialReleaseDate);
        return date && date >= thisMonthStart && date < nextMonthStart;
      })
    },
    {
      label: "Next Month",
      releases: upcoming.filter((release) => {
        const date = calendarDate(release.officialReleaseDate);
        return date && date >= nextMonthStart && date < laterThisYearStart;
      })
    },
    {
      label: "Later This Year",
      releases: upcoming.filter((release) => {
        const date = calendarDate(release.officialReleaseDate);
        return date && date >= laterThisYearStart && date < nextYearStart;
      })
    },
    {
      label: "TBD / Needs Review",
      releases: upcoming.filter((release) => !release.officialReleaseDate)
    }
  ].filter((group) => group.releases.length);
  return (
    <section className="release-calendar-panel">
      <div className="release-year-heading">
        <div>
          <p className="eyeline">Upcoming Drops</p>
          <h2>Next releases and preorder windows</h2>
        </div>
        <span className="light-pill">{upcoming.length} upcoming</span>
      </div>
      <div className="release-upcoming-list">
        {groups.map((group) => (
          <div className="release-upcoming-group" key={group.label}>
            <div className="release-month-heading">
              <h3>{group.label}</h3>
              <span>{group.releases.length} release{group.releases.length === 1 ? "" : "s"}</span>
            </div>
            {group.releases.map((release) => <ReleaseListRow key={release.id} release={release} onSelect={onSelect} />)}
          </div>
        ))}
        {!upcoming.length ? <EmptyState icon={CalendarDays} title="No upcoming releases" detail="Sync public sources or add the next known drop manually." /> : null}
      </div>
    </section>
  );
}

function ReleaseListRow({ release, onSelect }: { release: ReleaseDTO; onSelect: (release: ReleaseDTO) => void }) {
  const releaseDate = calendarDateParts(release.officialReleaseDate);
  const sourceUrl = releaseSourceUrl(release);
  return (
    <article className="release-list-row">
      <div className="release-list-date">
        <strong>{releaseDate ? releaseDate.day : "TBD"}</strong>
        <span>{releaseDate ? `${releaseDate.weekday} ${shortDate(release.officialReleaseDate)}` : "Needs date"}</span>
      </div>
      <div className="release-list-image">
        {release.productImage ? <Image src={release.productImage} alt="" width={56} height={56} unoptimized /> : <CalendarDays size={22} />}
      </div>
      <div className="release-list-main">
        <strong>{release.setName}</strong>
        <span>{release.productType || release.productTypes.split(",")[0]} - {release.region} - {releaseSourceLabel(release)}</span>
        <small>{releaseTimingLabel(release)}</small>
      </div>
      <div className="release-list-badges">
        <span className="light-pill">{releaseSourceBadgeLabel(release)}</span>
        <span className={`light-pill ${statusTone(release.confidence)}`}>{release.confidence} confidence</span>
        <span className={`light-pill ${releaseStatusTone(release)}`}>{releaseStatusLabel(release)}</span>
        <button className="mini-action" type="button" onClick={() => onSelect(release)}>
          View Details
        </button>
        {sourceUrl ? (
          <a className="mini-action icon-only" href={sourceUrl} target="_blank" rel="noreferrer" aria-label={`Open source for ${release.setName}`}>
            <ExternalLink size={14} />
          </a>
        ) : (
          <button className="mini-action icon-only warn" type="button" onClick={() => onSelect(release)} aria-label={`Source missing for ${release.setName}`}>
            <AlertTriangle size={14} />
          </button>
        )}
      </div>
    </article>
  );
}

function InfoBlock({ label, value }: { label: string; value: string }) {
  return (
    <div className="info-block">
      <small>{label}</small>
      <strong>{value}</strong>
    </div>
  );
}

function ReleaseDetailModal({
  release,
  isAdmin,
  busy,
  busyLabel,
  runAction,
  onClose
}: {
  release: ReleaseDTO;
  isAdmin: boolean;
  busy: boolean;
  busyLabel: string | null;
  runAction: ActionHandler;
  onClose: () => void;
}) {
  const actionUrl = releasePrimaryUrl(release);
  const sourceUrl = releaseSourceUrl(release);
  const statusLabel = releaseStatusLabel(release);
  const markConfirmedLabel = `Marking release confirmed ${release.id}`;
  const markReviewLabel = `Marking release review ${release.id}`;
  const saveSourceLabel = `Saving release source ${release.id}`;
  const statusReason =
    statusLabel === "Scheduled"
      ? "Trusted secondary calendar with product name and release date."
      : statusLabel === "Confirmed"
        ? "Trusted official, retailer, or manual source with product name and release date."
        : statusLabel === "TBD"
          ? "Real product tracked without a confirmed release date."
          : release.reviewReason || "Parser or source conflict needs review.";
  async function copySource() {
    if (!sourceUrl || typeof navigator === "undefined" || !navigator.clipboard) return;
    await navigator.clipboard.writeText(sourceUrl);
  }
  return (
    <div className="modal-backdrop" role="presentation">
      <article className="release-detail-modal app-light-surface" role="dialog" aria-modal="true" aria-label={`${release.setName} release details`}>
        <button className="modal-close" type="button" onClick={onClose} aria-label="Close release details">
          <X size={18} />
        </button>
        <div className="release-detail-top">
          <div className="release-image-card">
            {release.productImage ? <Image src={release.productImage} alt="" width={220} height={220} unoptimized /> : <CalendarDays size={46} />}
          </div>
          <div>
            <p className="eyeline">{release.status === "released" ? "Released" : "Upcoming Release"}</p>
            <h2>{release.setName}</h2>
            <span>{release.productType || release.releaseType} - {releaseTimingLabel(release)}</span>
            <div className="release-detail-badges">
              <span className={`light-pill ${statusTone(release.priority)}`}>{release.priority}</span>
              <span className={`light-pill ${statusTone(release.confidence)}`}>{release.confidence} confidence</span>
              <span className={`light-pill ${releaseStatusTone(release)}`}>{statusLabel}</span>
              {release.createdByManualEntry ? <span className="light-pill">Manual</span> : <span className="light-pill good">Synced</span>}
            </div>
          </div>
        </div>
        <div className="release-detail-grid">
          <InfoBlock label="Status" value={statusLabel} />
          <InfoBlock label="Release date" value={releaseDateLabel(release)} />
          <InfoBlock label="Preorder" value={release.preorderDate ? shortDate(release.preorderDate) : release.preorderWindowText || "TBD"} />
          <InfoBlock label="Product type" value={release.productType || release.productTypes.split(",")[0] || release.releaseType} />
          <InfoBlock label="Set name" value={release.setName} />
          <InfoBlock label="Region" value={release.region || "US"} />
          <InfoBlock label="Retailer" value={release.retailer || (release.pokemonCenterExclusiveVersion ? "Pokemon Center" : "TBD")} />
          <InfoBlock label="Pokemon Center exclusive" value={release.pokemonCenterExclusiveVersion ? "Yes" : "No"} />
          <InfoBlock label="Demand" value={release.estimatedDemand || release.demandRating} />
          <InfoBlock label="Source" value={releaseSourceLabel(release)} />
          <InfoBlock label="Last sync" value={release.lastSyncedAt ? dateTime(release.lastSyncedAt) : "Not synced"} />
        </div>
        <p className="release-review-note">{statusReason}</p>
        <section className={`release-source-card ${sourceUrl ? "" : "missing"}`}>
          <div className="release-source-card-heading">
            <div>
              <p className="eyeline">Source</p>
              <h3>{release.sourceName || (release.createdByManualEntry ? "Manual entry" : "Unknown source")}</h3>
            </div>
            <span className="light-pill">{releaseSourceBadgeLabel(release)}</span>
          </div>
          <div className="release-detail-grid">
            <InfoBlock label="Source type" value={release.sourceType || "manual"} />
            <InfoBlock label="Source URL" value={sourceUrl || "Source missing"} />
            <InfoBlock label="Parsed title / product" value={release.productName || release.releaseName || release.setName} />
          </div>
          {!sourceUrl ? (
            <p className="release-source-warning">
              <AlertTriangle size={16} />
              This release does not have a source link yet.
            </p>
          ) : null}
          <div className="release-detail-actions">
            {sourceUrl ? (
              <>
                <a className="light-action primary" href={sourceUrl} target="_blank" rel="noreferrer">
                  Open Source <ExternalLink size={14} />
                </a>
                <button
                  className="light-action"
                  type="button"
                  onClick={() =>
                    runAction("Copying source link", copySource, {
                      reload: false,
                      success: "Source link copied"
                    })
                  }
                >
                  Copy Source Link
                </button>
              </>
            ) : null}
            {actionUrl && actionUrl !== sourceUrl ? (
              <a className="light-action" href={actionUrl} target="_blank" rel="noreferrer">
                Open Product Page <ExternalLink size={14} />
              </a>
            ) : null}
          </div>
        </section>
        <p className="release-detail-notes">{release.notes || "No notes saved."}</p>
        {isAdmin ? (
          <section className="release-admin-card">
            <div className="release-source-card-heading">
              <div>
                <p className="eyeline">Admin Actions</p>
                <h3>Release controls</h3>
              </div>
            </div>
            <div className="release-admin-actions">
              <button
                className="light-action"
                disabled={busy}
                type="button"
                onClick={() =>
                  runAction(
                    markConfirmedLabel,
                    () =>
                      requestJson(`/api/radar/releases/${release.id}`, {
                        method: "PATCH",
                        body: JSON.stringify(
                          releasePatchPayload(release, {
                            status: "confirmed",
                            needsReview: false,
                            reviewReason: null,
                            confidence: release.confidence === "LOW" ? "MEDIUM" : release.confidence
                          })
                        )
                      }),
                    { success: "Release marked confirmed" }
                  )
                }
              >
                {busyLabel === markConfirmedLabel ? "Saving" : "Mark Confirmed"}
              </button>
              <button
                className="light-action"
                disabled={busy}
                type="button"
                onClick={() =>
                  runAction(
                    markReviewLabel,
                    () =>
                      requestJson(`/api/radar/releases/${release.id}`, {
                        method: "PATCH",
                        body: JSON.stringify(
                          releasePatchPayload(release, {
                            status: "needs_review",
                            needsReview: true,
                            reviewReason: release.reviewReason || "Marked for admin review from release detail."
                          })
                        )
                      }),
                    { success: "Release marked needs review" }
                  )
                }
              >
                {busyLabel === markReviewLabel ? "Saving" : "Mark Needs Review"}
              </button>
              <a className="light-action" href="#manual-release-form" onClick={onClose}>
                Edit Release
              </a>
              <button className="light-action" disabled type="button" title="Duplicate merge workflow is not automated yet.">
                Merge Duplicate
              </button>
              <button className="light-action" disabled type="button" title="Ignore/archive remains available from the full release admin form.">
                Ignore
              </button>
            </div>
            <form
              className="release-source-edit-form"
              onSubmit={(event) => {
                event.preventDefault();
                const form = event.currentTarget;
                const data = formJson(form);
                const nextSourceUrl = formString(data.sourceUrl);
                const nextSourceName = formString(data.sourceName);
                const nextSourceType = formString(data.sourceType);
                void runAction(
                  saveSourceLabel,
                  () =>
                    requestJson(`/api/radar/releases/${release.id}`, {
                      method: "PATCH",
                      body: JSON.stringify(
                        releasePatchPayload(release, {
                          sourceUrl: nextSourceUrl || null,
                          sourceName: nextSourceName || release.sourceName || "Manual source",
                          sourceType: nextSourceType || release.sourceType || "manual"
                        })
                      )
                    }),
                  { success: "Release source saved" }
                );
              }}
            >
              <TextInput name="sourceName" label="Source name" defaultValue={release.sourceName ?? ""} />
              <TextInput name="sourceType" label="Source type" defaultValue={release.sourceType || "manual"} />
              <TextInput name="sourceUrl" label="Add/Edit Source URL" type="url" defaultValue={sourceUrl ?? ""} />
              <button className="light-action primary" disabled={busy} type="submit">
                {busyLabel === saveSourceLabel ? "Saving Source" : "Save Source URL"}
              </button>
            </form>
          </section>
        ) : null}
        <div className="release-detail-actions">
          <button className="light-action" type="button" onClick={onClose}>Close</button>
        </div>
      </article>
    </div>
  );
}

function ReleaseManagementPanel({
  dashboard,
  busy,
  busyLabel,
  submit,
  runAction
}: {
  dashboard: DashboardDTO;
  busy: boolean;
  busyLabel: string | null;
  submit: SubmitHandler;
  runAction: ActionHandler;
}) {
  return (
    <>
      <section className="form-panel" id="manual-release-form">
        <h2>Add Manual Release</h2>
        <form
          className="form-grid"
          onSubmit={(event) =>
            submit(
              event,
              "Adding release",
              (form) => requestJson("/api/radar/releases", { method: "POST", body: JSON.stringify(formJson(form)) }),
              { success: "Release added" }
            )
          }
        >
          <TextInput name="setName" label="Set name" required />
          <TextInput name="releaseName" label="Public release name" />
          <SelectInput
            name="productType"
            label="Primary product type"
            options={productTypeOptions.map((value) => ({ value, label: value }))}
          />
          <SelectInput name="releaseType" label="Release type" options={["expansion", "product_drop", "preorder_window", "promo"].map(optionFromString)} />
          <TextInput name="officialReleaseDate" label="Release date" type="date" min="2020-01-01" />
          <TextInput name="preorderDate" label="Preorder date" type="date" min="2020-01-01" />
          <TextInput name="preorderWindowText" label="Preorder window text" placeholder="TBD, tomorrow, retailer window" />
          <TextInput name="region" label="Region" defaultValue="US" />
          <TextInput name="retailer" label="Retailer" placeholder="Pokemon Center, Target, Walmart" />
          <TextareaInput name="productTypes" label="Product types" placeholder="ETB, Booster Bundle" wide required />
          <TextInput name="productImage" label="Product image URL" />
          <TextInput name="productUrl" label="Product URL" />
          <SelectInput name="demandRating" label="Demand" options={priorities.map(optionFromString)} />
          <SelectInput name="estimatedDemand" label="Estimated demand" options={priorities.map(optionFromString)} />
          <SelectInput name="priority" label="Priority" options={priorities.map(optionFromString)} />
          <SelectInput name="sealedProductPriority" label="Sealed product priority" options={priorities.map(optionFromString)} />
          <label className="checkbox-label">
            <input name="pokemonCenterExclusiveVersion" type="checkbox" value="true" />
            Pokemon Center exclusive version
          </label>
          <TextareaInput name="chaseCards" label="Chase cards" wide />
          <TextareaInput name="productLinks" label="Product links" placeholder="https://..." wide />
          <TextInput name="sourceName" label="Source name" placeholder="Official Pokemon, manual note" />
          <TextInput name="sourceUrl" label="Source URL" />
          <SelectInput name="confidence" label="Confidence" options={priorities.map(optionFromString)} />
          <label className="checkbox-label">
            <input name="needsReview" type="checkbox" value="true" />
            Needs review
          </label>
          <TextInput name="reviewReason" label="Review reason" />
          <TextareaInput name="notes" label="Notes" wide />
          <button className="primary-action" disabled={busy} type="submit">
            <Plus size={16} />
            {busyLabel === "Adding release" ? "Adding" : "Add Release"}
          </button>
        </form>
      </section>
      <BulkImportPanel
        title="Bulk Release Import"
        endpoint="/api/radar/releases/import"
        busy={busy}
        busyLabel={busyLabel}
        submit={submit}
        sample={`setName,productType,officialReleaseDate,preorderDate,productTypes,pokemonCenterExclusiveVersion,chaseCards,demandRating,estimatedDemand,priority,sealedProductPriority,productLinks,notes\nMega Evolution-Chaos Rising,Build & Battle Box,2026-05-22,2026-05-08,\"Build & Battle Box, Booster Bundle, ETB\",true,Verify final chase card list,HIGH,HIGH,HIGH,HIGH,https://www.pokemon.com/uk/pokemon-news/get-a-pokemon-tcg-mega-evolution-chaos-rising-build-battle-box-early,Verify dates by region`}
      />
      <section className="form-panel">
        <h2>Edit Releases</h2>
        <div className="edit-stack">
          {dashboard.releases.length ? (
            dashboard.releases.map((release) => (
              <EditableRelease
                key={release.id}
                release={release}
                busy={busy}
                busyLabel={busyLabel}
                submit={submit}
                runAction={runAction}
              />
            ))
          ) : (
            <EmptyState icon={CalendarDays} title="No releases to edit" detail="Add a release first." />
          )}
        </div>
      </section>
    </>
  );
}

function EditableRelease({
  release,
  busy,
  busyLabel,
  submit,
  runAction
}: {
  release: ReleaseDTO;
  busy: boolean;
  busyLabel: string | null;
  submit: SubmitHandler;
  runAction: ActionHandler;
}) {
  const saveLabel = `Saving release ${release.id}`;
  return (
    <form
      className="edit-card"
      onSubmit={(event) =>
        submit(
          event,
          saveLabel,
          (form) =>
            requestJson(`/api/radar/releases/${release.id}`, {
              method: "PATCH",
              body: JSON.stringify(formJson(form))
            }),
          { reset: false, success: "Release saved" }
        )
      }
    >
      <div className="edit-card-heading">
        <div>
          <strong>{release.setName}</strong>
          <span>{release.officialReleaseDate ? `${shortDate(release.officialReleaseDate)} - ${Math.max(0, release.daysUntilRelease ?? 0)} days` : "Release date TBD"}</span>
        </div>
        <span className={`chip ${statusTone(release.priority)}`}>{release.priority}</span>
      </div>
      <div className="form-grid">
        <input name="sourceType" type="hidden" value={release.sourceType} />
        <input name="createdByManualEntry" type="hidden" value={release.createdByManualEntry ? "true" : "false"} />
        <TextInput name="setName" label="Set name" defaultValue={release.setName} required />
        <TextInput name="releaseName" label="Public release name" defaultValue={release.releaseName ?? ""} />
        <SelectInput
          name="productType"
          label="Primary product type"
          defaultValue={release.productType ?? productTypeOptions[0]}
          options={productTypeOptions.map((value) => ({ value, label: value }))}
        />
        <SelectInput name="releaseType" label="Release type" defaultValue={release.releaseType} options={["expansion", "product_drop", "preorder_window", "promo"].map(optionFromString)} />
        <TextInput
          name="officialReleaseDate"
          label="Release date"
          type="date"
          min="2020-01-01"
          defaultValue={toDateInput(release.officialReleaseDate)}
        />
        <TextInput
          name="preorderDate"
          label="Preorder date"
          type="date"
          min="2020-01-01"
          defaultValue={toDateInput(release.preorderDate)}
        />
        <TextInput name="preorderWindowText" label="Preorder window text" defaultValue={release.preorderWindowText ?? ""} />
        <TextInput name="region" label="Region" defaultValue={release.region || "US"} />
        <TextInput name="retailer" label="Retailer" defaultValue={release.retailer ?? ""} />
        <TextareaInput name="productTypes" label="Product types" defaultValue={release.productTypes} wide required />
        <TextInput name="productImage" label="Product image URL" defaultValue={release.productImage ?? ""} />
        <TextInput name="productUrl" label="Product URL" defaultValue={release.productUrl ?? ""} />
        <SelectInput name="demandRating" label="Demand" defaultValue={release.demandRating} options={priorities.map(optionFromString)} />
        <SelectInput
          name="estimatedDemand"
          label="Estimated demand"
          defaultValue={release.estimatedDemand}
          options={priorities.map(optionFromString)}
        />
        <SelectInput name="priority" label="Priority" defaultValue={release.priority} options={priorities.map(optionFromString)} />
        <SelectInput
          name="sealedProductPriority"
          label="Sealed product priority"
          defaultValue={release.sealedProductPriority}
          options={priorities.map(optionFromString)}
        />
        <label className="checkbox-label">
          <input
            name="pokemonCenterExclusiveVersion"
            type="checkbox"
            value="true"
            defaultChecked={release.pokemonCenterExclusiveVersion}
          />
          Pokemon Center exclusive version
        </label>
        <TextareaInput name="chaseCards" label="Chase cards" defaultValue={release.chaseCards ?? ""} wide />
        <TextareaInput name="productLinks" label="Product links" defaultValue={release.productLinks ?? ""} wide />
        <TextInput name="sourceName" label="Source name" defaultValue={release.sourceName ?? ""} />
        <TextInput name="sourceUrl" label="Source URL" defaultValue={release.sourceUrl ?? ""} />
        <SelectInput name="confidence" label="Confidence" defaultValue={release.confidence} options={priorities.map(optionFromString)} />
        <TextInput name="status" label="Status" defaultValue={release.status} />
        <label className="checkbox-label">
          <input name="needsReview" type="checkbox" value="true" defaultChecked={release.needsReview} />
          Needs review
        </label>
        <TextInput name="reviewReason" label="Review reason" defaultValue={release.reviewReason ?? ""} />
        <TextareaInput name="notes" label="Notes" defaultValue={release.notes ?? ""} wide />
      </div>
      <div className="form-actions">
        <button className="mini-action solid" disabled={busy} type="submit">
          <Save size={14} />
          {busyLabel === saveLabel ? "Saving" : "Save"}
        </button>
        <button
          className="mini-action danger"
          disabled={busy}
          type="button"
          onClick={() =>
            runAction(
              `Deleting release ${release.id}`,
              () => requestJson(`/api/radar/releases/${release.id}`, { method: "DELETE" }),
              {
                confirm: `Delete ${release.setName}?`,
                success: "Release deleted"
              }
            )
          }
        >
          <Trash2 size={14} />
          Delete
        </button>
      </div>
    </form>
  );
}

